{
  			// we bring this call out of the monitor block to prevent a potential deadlock whereby we chain
  			// state_mon -> control_mon (there exist numerous dependencies control_mon -> state_mon...

  		boolean	call_filesExist	= false;

   		try{
  			state_mon.enter();

	  		int	old_state = state_set_by_method;

			// note: there is a DIFFERENCE between the state held on the DownloadManager and
		    // that reported via getState as getState incorporated DiskManager states when
		    // the DownloadManager is INITIALIZED
		  	//System.out.println( "DM:setState - " + _state );

	  		if ( old_state != _state ){

	  			state_set_by_method = _state;

	  			if ( state_set_by_method != DownloadManager.STATE_QUEUED ){

	  					// only maintain this while queued

	  				activation_bloom = null;

	  				if ( 	state_set_by_method == DownloadManager.STATE_STOPPED ||
	  						state_set_by_method == DownloadManager.STATE_DOWNLOADING ||
	  						state_set_by_method == DownloadManager.STATE_SEEDING ){

	  						// don't need this anymore once stopped or active

	  					activation_count = 0;
	  				}
	  			}

	  			if (state_set_by_method == DownloadManager.STATE_QUEUED ){


	  				// don't pick up errors regarding missing data while queued.
	  				// We'll do that when the torrent starts.  Saves time at startup
	  				// pick up any errors regarding missing data for queued SEEDING torrents
//	  				if (  download_manager.getAssumedComplete()){
//
//	  					call_filesExist	= true;
//	  				}

	  			}else if ( state_set_by_method == DownloadManager.STATE_ERROR ){

		      		// the process of attempting to start the torrent may have left some empty
		      		// directories created, some users take exception to this.
		      		// the most straight forward way of remedying this is to delete such empty
		      		// folders here

	  				TOTorrent	torrent = download_manager.getTorrent();

	  				if ( torrent != null && !torrent.isSimpleTorrent()){

	  					File	save_dir_file	= download_manager.getAbsoluteSaveLocation();

	  					if ( save_dir_file != null && FileUtil.exists( save_dir_file ) && save_dir_file.isDirectory()){

	  						TorrentUtils.recursiveEmptyDirDelete( save_dir_file, false );
	  					}
	  				}
	  			}

	  			if ( old_state == DownloadManager.STATE_STOPPED ){

	  				download_manager.setStopReason( null );
	  			}
	  		}
  		}finally{

  			state_mon.exit();
  		}

  		if ( call_filesExist ){

  			filesExist( true, false );
  		}

  		if ( _inform_changed ){

  			download_manager.informStateChanged();
  		}
  	}

{
		try{
			state_mon.enter();

			if ( force_start != _force_start ){

				force_start = _force_start;

				int	state = getState();

				if (	force_start &&
						(	state == DownloadManager.STATE_ERROR ||
							state == DownloadManager.STATE_STOPPED ||
							state == DownloadManager.STATE_QUEUED )) {

						// Start it!  (Which will cause a stateChanged to trigger)

					setState(DownloadManager.STATE_WAITING, false );
				}
		    }
		}finally{

			state_mon.exit();
		}

			// "state" includes the force-start setting

		download_manager.informStateChanged();
	}

{
		if (_assumedComplete) {
			long completedOn = download_manager_state.getLongParameter(DownloadManagerState.PARAM_DOWNLOAD_COMPLETED_TIME);
			if (completedOn <= 0) {
				long now =SystemTime.getCurrentTime();

				download_manager_state.setLongParameter( DownloadManagerState.PARAM_DOWNLOAD_COMPLETED_TIME, now );

				long last_file = download_manager_state.getLongParameter( DownloadManagerState.PARAM_DOWNLOAD_FILE_COMPLETED_TIME );

				if ( last_file <= 0 ){

					Runnable set_it = 
						new Runnable()
						{
							public void
							run()
							{

									// get a sensible value from actual files - useful when adding-for-seeding

								long	last_mod = 0;

								DiskManagerFileInfo[] files = getDiskManagerFileInfoSet().getFiles();

								for ( DiskManagerFileInfo file: files ){

									if ( !file.isSkipped()){

										File f = file.getFile( true );

										if ( f.length() == file.getLength()){

											long mod = f.lastModified();

											if ( mod > last_mod ){

												last_mod = mod;
											}
										}
									}
								}

								if ( last_mod == 0 ){

									last_mod = now;
								}

								download_manager_state.setLongParameter( DownloadManagerState.PARAM_DOWNLOAD_FILE_COMPLETED_TIME, last_mod );

								if ( last_mod < now ){

										// update with more useful value

									download_manager_state.setLongParameter( DownloadManagerState.PARAM_DOWNLOAD_COMPLETED_TIME, last_mod );
								}
							}
						};

					synchronized( init_lock ){

						if ( !initialised ){

							post_init_tasks.add( set_it );

							set_it = null;
						}
					}

					if ( set_it != null ){

						set_it.run();
					}
				}
			}
		}else{
			if ( filePriorityChanged ){

					// download no longer complete due to user switching file from DND - reset

				download_manager_state.setLongParameter( DownloadManagerState.PARAM_DOWNLOAD_COMPLETED_TIME, 0 );
			}
		}

		if (assumedComplete == _assumedComplete) {
			return;
		}

		//Logger.log(new LogEvent(this, LogIDs.CORE, "setAssumedComplete("
		//		+ _assumedComplete + ") was " + assumedComplete));

		assumedComplete = _assumedComplete;

		if (!assumedComplete) {
			controller.setStateDownloading();
		}

		// NOTE: We don't set "stats.setDownloadCompleted(1000)" anymore because
		//       we can be in seeding mode with an unfinished torrent

		if ( position != -1 && globalManager.contains( this )){

			// we are in a new list, move to the top of the list so that we continue
			// seeding.
			// -1 position means it hasn't been added to the global list.  We
			// shouldn't touch it, since it'll get a position once it's adding is
			// complete. Also check explicitly that it is known to the global manager
			// as it is possible to come through here twice during init

			DownloadManager[] dms = { DownloadManagerImpl.this };

			// pretend we are at the bottom of the new list
			// so that move top will shift everything down one

			position = globalManager.getDownloadManagers().size() + 1;

			if ( _assumedComplete ){

				if (COConfigurationManager.getBooleanParameter( CFG_MOVE_COMPLETED_TOP )){

					globalManager.moveTop(dms);

				} else {

					globalManager.moveEnd(dms);
				}
			}else{

					// moved back to downloading - use the open-torrent-options default to decide where to put the download

				int qp = COConfigurationManager.getIntParameter( "Add Torrent Queue Position", 1 );

				if ( qp == 0 ){

					globalManager.moveTop(dms);

				}else{

					globalManager.moveEnd(dms);
				}
			}

			// we left a gap in incomplete list, fixup

			globalManager.fixUpDownloadManagerPositions();
		}

		listeners.dispatch(LDT_COMPLETIONCHANGED, new Object[] {
				this,
			Boolean.valueOf(_assumedComplete)
		});
	}

{
		try{
			listeners_mon.enter();

			listeners.dispatch( LDT_DOWNLOADCOMPLETE, new Object[]{ this });

		}finally{

			listeners_mon.exit();
		}
	}

{
	    if ( !never_downloaded ){

	    	setAssumedComplete(true);

	    	informDownloadEnded();
	    }

	    TRTrackerAnnouncer	tc = getTrackerClient();

	    if ( tc != null ){

	    	DiskManager	dm = getDiskManager();

	    		// only report "complete" if we really are complete, not a dnd completion event

	    	boolean globalMask = COConfigurationManager.getBooleanParameter( ConfigKeys.Transfer.BCFG_PEERCONTROL_HIDE_PIECE );

	    	Boolean dmMask = download_manager_state.getOptionalBooleanAttribute( DownloadManagerState.AT_MASK_DL_COMP_OPTIONAL );

	    	boolean mask = dmMask==null?globalMask:dmMask;

	    	if ( dm != null && dm.getRemaining() == 0 && !mask ){

	    		tc.complete( never_downloaded );
	    	}
	    }
	}

{
    	try{
    		resume_handler.saveResumeData( interim_save );

    	}catch( Exception e ){

    		if ( interim_save && canFailureBeIgnored( e )){

    			return;
    		}

    		throw( e );
    	}
    }

{
        DownloadEndedProgressImpl progress = new DownloadEndedProgressImpl();

        AEThread2.createAndStartDaemon( "DownloadEnded", ()->{

        		moveDownloadFilesWhenEndedOrRemoved( false, true, progress, start_of_day );
        	});

        return( progress );
    }

{
		if ( check_in_progress && interim_save ){

				// while we are rechecking it is important that an interim save doesn't come
				// along and overwrite the persisted resume data. This is because should we crash
				// while rechecking we need the persisted state to be unchanged so that on
				// restart the rechecking occurs again

				// a non-interim save means that the user has decided to stop the  download (or some
				// other such significant event) so we just persist the current state

			return;
		}

			// if file caching is enabled then this is an important time to ensure that the cache is
			// flushed as we are going to record details about the accuracy of written data.
			// First build the resume map from the data (as updates can still be goin on)
			// Then, flush the cache. This means that on a successful flush the built resume
			// data matches at least the valid state of the data
			// Then update the torrent

		DiskManagerFileInfo[]	files = disk_manager.getFiles();

		/*
		if ( !use_fast_resume ){

				// flush cache even if resume disable as this is a good point to ensure that data
				// is persisted anyway

			for (int i=0;i<files.length;i++){

				files[i].flushCache();
			}

			return;
		}
		*/

		boolean	was_complete = isTorrentResumeDataComplete( disk_manager.getDownloadManager().getDownloadState());

		if ( was_complete && check_interrupted ){

				// piece completion state not usable, stick with the previous state of affairs

			return;
		}

		DiskManagerPiece[] pieces	= disk_manager.getPieces();

			//build the piece byte[]

		byte[] resume_pieces = new byte[pieces.length];

		for (int i = 0; i < resume_pieces.length; i++) {

			DiskManagerPiece piece = pieces[i];

				// if we are terminating due to az closure and this has interrupted a recheck then
				// make sure that the recheck continues appropriately on restart

			if ( stopped_for_close && check_interrupted && i >= check_position ){

				resume_pieces[i] = PIECE_RECHECK_REQUIRED;

			}else if ( piece.isDone()){

				resume_pieces[i] = PIECE_DONE;

		  	}else if ( piece.getNbWritten() > 0 ){

		  		resume_pieces[i] = PIECE_STARTED;

		  	}else{

				resume_pieces[i] = PIECE_NOT_DONE;
		  	}
		}

		Map	resume_data = new HashMap();

		resume_data.put( "resume data", resume_pieces );

		Map partialPieces = new HashMap();

		for (int i = 0; i < pieces.length; i++) {

			DiskManagerPiece piece = pieces[i];

				// save the partial pieces for any pieces that have not yet been completed
				// and are in-progress (i.e. have at least one block downloaded)

			boolean[] written = piece.getWritten();

			if (( !piece.isDone()) && piece.getNbWritten() > 0 && written != null ){

				boolean	all_written = true;

				for (int j = 0; j < written.length; j++) {

					if ( !written[j] ){

						all_written = false;

						break;
					}
				}

				if ( all_written ){

						// just mark the entire piece for recheck as we've stopped the torrent at the
						// point where a check-piece was, or was about to be, scheduled

					resume_pieces[ i ] = PIECE_RECHECK_REQUIRED;

				}else{

					List blocks = new ArrayList();

					for (int j = 0; j < written.length; j++) {

						if (written[j]){

							blocks.add(new Long(j));
						}
					}

					partialPieces.put("" + i, blocks);
				}
			}
		}

		resume_data.put("blocks", partialPieces);

		long lValid;

		if ( check_interrupted ){

				// set validity to what it was before the check started

			lValid = check_resume_was_valid?1:0;

		}else if ( interim_save ){

				// set invalid so that not-done pieces get rechecked on startup

			lValid = 0;

		}else{

			lValid = 1;
		}

		resume_data.put("valid", new Long(lValid));

		for (int i=0;i<files.length;i++){

			files[i].flushCache();
		}

	  		// OK, we've got valid resume data and flushed the cache

		boolean	is_complete = isTorrentResumeDataComplete( pieces.length, resume_data );

		if ( was_complete && is_complete ){

	  		// no change, no point in writing

		}else{

			saveResumeData( resume_data );
		}
	}

{
		Map	resume_map = new HashMap();

		resume_map.put( "data", resume_data );

		download_manager_state.setResumeData( resume_map );
	}

{
		if ( finish_in_progress != null ){

			// System.out.println( "Finish in prog" );

			if ( finish_in_progress.isComplete()){

				finish_in_progress = null;

				// System.out.println( "Finished" );
			}else{

				return;
			}
		}

		try{
			// first off update the stats so they can be used by subsequent steps

			updateStats();

			updateTrackerAnnounceInterval();

			doConnectionChecks();

			processPieceChecks();

			if ( finish_in_progress != null ){

				// get off the scheduler thread while potentially long running operations
				// complete

				return;
			}

			// note that seeding_mode -> torrent totally downloaded, not just non-dnd files
			// complete, so there is no change of a new piece appearing done by a means such
			// as
			// background periodic file rescans

			if(!seeding_mode){

				checkCompletedPieces(); // check to see if we've completed anything else
			}

			checkBadPieces();

			checkInterested(); // see if need to recheck Interested on all peers

			piecePicker.updateAvailability();

			checkCompletionState(); // pick up changes in completion caused by dnd file changes

			if ( finish_in_progress != null ){

				// get off the scheduler thread while potentially long running operations
				// complete

				return;
			}

			checkSeeds();

			if ( seeding_mode ){

				if(mainloop_loop_count % MAINLOOP_FIVE_SECOND_INTERVAL == 0){

					hash_handler.update();
				}
			}else{
				// if we're not finished

				checkRequests();

				piecePicker.allocateRequests();

				checkRescan();
				checkSpeedAndReserved();

				check99PercentBug();
			}

			updatePeersInSuperSeedMode();
			doUnchokes();

			if(mainloop_loop_count % MAINLOOP_ONE_SECOND_INTERVAL == 0){

				my_peer.update();
			}

		}catch(Throwable e){

			Debug.printStackTrace(e);
		}
		mainloop_loop_count++;
	}

{
		if(mainloop_loop_count % MAINLOOP_ONE_SECOND_INTERVAL != 0){

			return;
		}

		boolean dm_done = disk_mgr.getRemainingExcludingDND() == 0;

		if(seeding_mode){

			if(!dm_done){

				seeding_mode = false;

				_timeStartedSeeding = -1;
				_timeStartedSeeding_mono = -1;
				_timeFinished_mono = 0;

				synchronized( outbound_ignore_addresses ){

					Iterator<Integer> it =  outbound_ignore_addresses.values().iterator();

					while( it.hasNext()){

						int rc = it.next();

						if ( rc == Transport.CR_NOT_INTERESTED_UPLOAD_ONLY || rc == Transport.CR_UPLOAD_TO_UPLOAD ){

							it.remove();
						}
					}
				}

				Logger.log(new LogEvent(disk_mgr.getTorrent(), LOGID, "Turning off seeding mode for PEPeerManager"));
			}

		}else{

			if(dm_done){

				checkFinished(false);

				if(seeding_mode){

					Logger.log(new LogEvent(disk_mgr.getTorrent(), LOGID, "Turning on seeding mode for PEPeerManager"));

				}
			}
		}
	}

{
		if ( !closing ){

			long now_mono = SystemTime.getMonotonousTime();

			if (!b){

				if ( snubbed_time_mono >= 0 ){

					snubbed_time_mono = -1;

					manager.decNbPeersSnubbed();
				}
			}else if ( snubbed_time_mono < 0 ){

				snubbed_time_mono = now_mono;

				manager.incNbPeersSnubbed();
			}
		}
	}
